    sensitivity=obj({'factor':S('Actual changed method, conformer, coordinate or reference'),'baseline_value':N,'alternative_value':N,'difference':N,'unit':S('Explicit unit'),'baseline_record_ids':REFS,'alternative_record_ids':REFS,'uncertainty_interpretation':S('Bound from actual comparisons; not missing jobs'),'evidence_files':EVID})
    result=obj({'paper_id':{'const':pid},'schema_version':{'const':'batch4.expanded.v1'},'status':enum('complete','bounded_failure'),'methods':obj({'primary':method,'sensitivity':method},['primary']),'calculation_records':arr(record),'results':obj({k:v['schema'] for k,v in s['panels'].items()}),'hypotheses':arr(obj({'id':S('Hypothesis ID'),'claim':S('Falsifiable proposition'),'discriminating_control':S('Actual control that could refute it'),'assessment':enum('supported','refuted','not_distinguishable'),'record_ids':REFS,'evidence_files':EVID}),2),'sensitivity':arr(sensitivity),'conclusion':obj({'assessment':enum('supported','refuted','not_distinguishable','incomplete'),'statement':S('Evidence-bound scientific conclusion'),'supported_scope':S('Local model only'),'limits':S('Unresolved mechanisms/uncertainty'),'evidence_files':EVID}),'evidence_files':EVID,'resource_usage':obj({'scientific_engine_starts':{'type':'integer','minimum':0},'successful_jobs':{'type':'integer','minimum':0},'failed_jobs':{'type':'integer','minimum':0},'restart_count':{'type':'integer','minimum':0},'allocated_cores':{'type':'integer','minimum':0},'summed_job_wall_hours':{'type':'number','minimum':0},'cpu_core_hours':{'type':'number','minimum':0},'elapsed_calendar_hours':{'type':'number','minimum':0},'accounting_file':PATH}),'failure_report':obj({'attempted_scope':S('Scope actually attempted'),'cause':S('Observed issue'),'missing_endpoints':arr(S('Required missing endpoint')),'diagnostic_files':EVID})},['paper_id','schema_version','status','methods','calculation_records','conclusion','evidence_files','resource_usage'])
    # A pre-engine input/capability gate can fail before any real method or job exists.
    # Empty records must never force fabricated logs or count as scientific completion.
    result['properties']['methods']['required']=[]
    result['properties']['calculation_records']['minItems']=0
    result['properties']['failure_report']['properties']['stage']=enum('pre_engine','engine_or_analysis')
    result['$schema']='https://json-schema.org/draft/2020-12/schema'
    result['allOf']=[{'if':{'properties':{'status':{'const':'complete'}}},'then':{'required':['results','hypotheses','sensitivity'],'properties':{'methods':{'required':['sensitivity']},'calculation_records':{'contains':{'properties':{'kind':{'enum':['minimum','transition_state','single_point','constrained_diagnostic','excited_state','kinetic_analysis']}}}},'conclusion':{'properties':{'assessment':{'enum':['supported','refuted','not_distinguishable']}}}}}},{'if':{'properties':{'status':{'const':'bounded_failure'}}},'then':{'required':['failure_report'],'properties':{'conclusion':{'properties':{'assessment':{'const':'incomplete'}}}}}}]
    result['allOf'][0]['then']['properties']['methods']['required']=['primary','sensitivity']
    result['allOf'][0]['then']['properties']['calculation_records']['minItems']=1
