    from rdkit.Chem.EnumerateStereoisomers import EnumerateStereoisomers,StereoEnumerationOptions
    registry={'paper_id':pid,'coordinate_policy':'Only given reactant starters; new graph definitions are not optimized minima or TSs. Explicit atom maps, charge and multiplicity take priority over distance-based bond guesses.','species':[],'construction_definitions':{k:v for k,v in s['objects'].items() if k!='molecules'}}
