            if it['id'].startswith('silylene_') and 'coordinates' in it:
                key=f"tasks/final_verified_autonomous_research/{pid}/agent_input/data/inputs/{it['coordinates']}";g=GRAPH[key]
                bonds=deepcopy(g['bonds'])
                # Coordination/valence representation: neutral divalent Si, single Si-N bond.
                si=7 if '1_singlet' in it['id'] else 1;nit=8 if si==7 else 36
