        old=json.loads((agent/'data/inputs/system.json').read_text());long=next(x for x in registry['species'] if x['id']=='long_radical')
        long['mapping_override']='Do not use generated local long SMILES row maps for homologous comparisons; use retained short maps plus54/55/56 as given below.'
