        long['homologous_atoms']=deepcopy(g['atoms'])+[{'map_id':54,'element':'C'},{'map_id':55,'element':'H'},{'map_id':56,'element':'H'}]
        long['homologous_bonds']=[{'atoms':x['atoms_1based'],'order':x['order']} for x in old['bonds'] if set(x['atoms_1based'])!={13,14}]+[{'atoms':[13,54],'order':1},{'atoms':[54,14],'order':1},{'atoms':[54,55],'order':1},{'atoms':[54,56],'order':1}]
        long['added_atoms']=[{'map_id':54,'element':'C'},{'map_id':55,'element':'H'},{'map_id':56,'element':'H'}]
