def evaluator(pid,s,source_rows):
    source_ids=['source_'+str(i+1) for i in range(len(source_rows))]+['upgrade_design']
    identity='Inspect species_registry, every input/geometry mapping and real raw log. Verify stoichiometry, charge/multiplicity, method/state, stationarity or constrained label, and consistent thermochemistry. '+s['boundary']
    kps=[{'key_point_id':'kp_identity','statement':'Correct objects, chemical bookkeeping and valid evidence.','expected':identity,'evidence_ids':source_ids}]
    rules=[{'rule_id':'rule_identity','reference_id':'kp_identity','type':'condition','expected':identity,'binding':{'artifact_paths':['report/results.json','report/report.md'],'fields':['$.calculation_records','$.methods','$.results'],'comparison':identity}}]
    rubric=[{'id':'identity','max_score':10,'description':identity,'rule_ids':['rule_identity']}]
    for (name,p),weight in zip(s['panels'].items(),[30,25,15]):
        exp=p['judge']+' Recompute quantities from identified raw jobs and evidence files. Check all required named matrix cells; prose or a legacy scalar cannot replace this endpoint. A scientific ambiguity is valid only after the relevant controls exist. Non-saddle/collapse alternatives require actual profiles and both endpoints, not failed optimization. A same-basin comparison may omit nonexistent independent numeric operands only after separate complete searches, mapped identity and stationarity demonstrate collapse; this never excuses a missing control. New numerical reference and tolerances are pending; never choose a preferred value or broaden a legacy tolerance to excuse wrong identity.'
        kps.append({'key_point_id':'kp_'+name,'statement':p['text'],'expected':exp,'evidence_ids':source_ids})
        rules.append({'rule_id':'rule_'+name,'reference_id':'kp_'+name,'type':'condition','expected':exp,'binding':{'artifact_paths':['report/results.json','report/report.md'],'fields':['$.results.'+name,'$.calculation_records','$.evidence_files'],'comparison':exp},'evidence_policy':'Resolve every record/path, inspect content not filenames, and audit dimensions/units, mapping and arithmetic.'})
        rubric.append({'id':name,'max_score':weight,'description':exp,'rule_ids':['rule_'+name]})
    exp='Use actual changed-model results and at least two falsifiable explanations. Recalculate sensitivity differences and relate uncertainty to ordering/support sets. '+s['errors']
    kps.append({'key_point_id':'kp_robustness','statement':'Discriminating control and quantitative robustness.','expected':exp,'evidence_ids':source_ids})
    rules.append({'rule_id':'rule_robustness','reference_id':'kp_robustness','type':'condition','expected':exp,'binding':{'artifact_paths':['report/results.json','report/report.md'],'fields':['$.hypotheses','$.sensitivity','$.results'],'comparison':exp}})
    rubric.append({'id':'robustness','max_score':10,'description':exp,'rule_ids':['rule_robustness']})
    cexp='Accept support, refutation or evidence-complete non-distinguishability on equal terms. No required author winner. Missing comparison, wrong electronic state/reference, fabricated or absent raw evidence invalidates dependent conclusions; bounded_failure is not scientific pass. '+s['errors']
    conc={'conclusion_id':'conclusion_local_investigation','claim_role':'final','statement':s['title'],'expected':cexp,'supporting_key_point_ids':[r['key_point_id'] for r in kps],'evidence_ids':source_ids}
    rules.append({'rule_id':'rule_conclusion','reference_id':conc['conclusion_id'],'type':'semantic','expected':cexp,'binding':{'artifact_paths':['report/results.json','report/report.md'],'fields':['$.conclusion','$.results','$.hypotheses','$.sensitivity'],'comparison':cexp}})
    rubric.append({'id':'conclusion','max_score':10,'description':cexp,'rule_ids':['rule_conclusion']})
    evidence=[{'evidence_id':'source_'+str(i+1),'source':r,'scope':'Source chemistry and original protocol only; not expanded-reference validation.'} for i,r in enumerate(source_rows)]
    evidence.append({'evidence_id':'upgrade_design','source':{'path':'evaluation/reference_validation_plan.md','date':'2026-09-27'},'scope':'Benchmark-authored expanded controls, no new reference values calculated.'})
    failures=[{'failure_id':'cf_'+k,'severity':'scientifically serious','condition':v} for k,v in {'identity':s['errors'],'missing_matrix':'Only old scalar/descriptor results or missing core named comparisons, even when labelled complete or uncertain. Optional work is not required.','evidence':'Results unsupported by real matching raw files, invented jobs/energies/modes, or source answers presented as independent calculations. Honest bounded failure is not fabrication but does not complete the science.','reference':'Wrong composition, charge/spin, medium, E versus G, standard state or common energy zero in a comparison.','overclaim':'Local thermochemistry/descriptor interpreted as full catalytic mechanism, exact product yield, polymer or device performance without corresponding evidence.'}.items()]
    return {'reference_key_points.json':{'paper_id':pid,'items':kps},'reference_conclusions.json':{'paper_id':pid,'items':[conc]},'scoring_rules.json':{'paper_id':pid,'scoring_policy':'dual_axis_100.scientific_results.v1','rules':rules,'scientific_rubric':rubric,'reference_stage':'blocked_input_preparation' if s['blocked'] else 'development_pending_expanded_reference_calculations','scoring_notes':['Schema/transport validation does not establish scientific correctness or calibrated scoring.','No new target tolerance is frozen; calibrate using complete paths, conformer/method sensitivity and source measurement uncertainty.','Supporting, contradictory and fully evidenced indistinguishable results receive equal endpoint credit.','Uncomputed core controls receive no endpoint credit; bounded failure cannot acquire a completion PASS.']},'critical_failures.json':{'paper_id':pid,'items':failures},'evidence_map.json':{'paper_id':pid,'evidence':evidence}}

def refresh(package,pid,mode):
    entries=package_payload_entries(package)
    dump(package/'package_manifest.json',{'paper_id':pid,'task_type':mode,'package_format':1,'agent_input_root':'agent_input','package_content_sha256':package_content_hash(entries),'entries':[e.model_dump(mode='json') for e in entries]})

def status_write(done):
    lines=['# 第 4 批升级状态','', '更新：2026-09-27。开发包实现与科学参考验证分列；本轮量化引擎启动0。','']
    for pid in IDS:
        rec=done.get(pid)
        lines.append(f"- {pid}：{rec['status'] if rec else '待生成／审查定义已保存'}"+(f"；AR/PR已保存；新参考尚未计算。" if rec else ''))
    (B/'STATUS.md').write_text('\n'.join(lines)+'\n')

def build_one(pid):
    s=SPECS[pid];source_record=next(x for x in ASSIGN['records'] if x['paper_id']==pid)
    sources=deepcopy(SOURCES[pid])
    # Use every directly inspected actual PDF page, including pages added during evidence correction.
    for row in sources:
        stem=Path(row['path']).stem
        row['pdf_pages_1_based']=sorted(int(re.search(r'_p(\d+)\.txt$',p.name).group(1)) for p in (B/'source_review'/pid).glob(stem+'_p*.txt'))
        row.pop('pdf_pages',None)
    official=B/'source_review'/pid/'publisher_formal_SI.pdf'
    if official.exists():sources.append({'path':str(official.relative_to(ROOT)),'sha256':sha(official),'pdf_pages_1_based':[10,11,12,13,14,20,21,22,32],'page_count':117,'publisher_url':'https://media.springernature.com/original/springer-static/esm/art%3A10.1038%2Fs41467-025-68049-w/MediaObjects/41467_2025_68049_MOESM1_ESM.pdf'})
    status='blocked' if s['blocked'] else 'implemented_pending_expanded_reference'
    packages=[]
    for mode in MODES:
        src=ROOT/('tasks/final_verified_'+mode)/pid;target=DEST/mode/pid
        if not target.exists():shutil.copytree(src,target)
        auditpath=target/'evaluation/task_provenance/upgrade_audit.json'
        if auditpath.exists():
            prior=json.loads(auditpath.read_text())
            if prior.get('implementation_owner')!='batch4.build_batch':raise RuntimeError('Existing independent progress; refuse to overwrite '+str(target))
        snapshot_records={}
        for p in sorted(src.rglob('*')):
            if not p.is_file():continue
            rel=p.relative_to(src);snap=Path('evaluation/legacy_final_snapshot')/(str(rel)+'.snapshot');q=target/snap
            if q.exists() and q.read_bytes()!=p.read_bytes():raise RuntimeError('Source drift '+str(p))
            if not q.exists():q.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,q)
            snapshot_records[str(rel)]={'snapshot':str(snap),'sha256':sha(p),'size':p.stat().st_size}
        # Archive old active claims as snapshot only; leave no old PASS or contradictory live guide.
        for p in list((target/'evaluation').rglob('*')):
            if p.is_file() and 'legacy_final_snapshot' not in p.parts and p.name not in ['upgrade_audit.json']:
                if p.name in ['reference_key_points.json','reference_conclusions.json','scoring_rules.json','critical_failures.json','evidence_map.json','reference_validation_plan.md']:continue
                p.unlink()
        agent=target/'agent_input'
        # Both modes get identical authorized public source data.
        arsrc=ROOT/'tasks/final_verified_autonomous_research'/pid/'agent_input/data'
        if mode=='paper_reproduction':
            for p in list((agent/'data').rglob('*')):
                if p.is_file() and not (arsrc/p.relative_to(agent/'data')).exists() and p.name not in ['species_registry.json','research_matrix.json','public_sources.json','state_definition.json','kinetic_observations.json']:p.unlink()
            for p in arsrc.rglob('*'):
                if p.is_file():q=agent/'data'/p.relative_to(arsrc);q.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,q)
        # Remove answer-bearing source Cu intermediates and old endpoint coordinates now used for path discovery.
        if pid in ['paper_db6c4e0558113873','paper_4e9774f4128551d3']:
            for p in (agent/'data/inputs').glob('*.xyz'):p.unlink()
        # Scope text in old public JSON is retired when it directly contradicts new required scope.
        for p in (agent/'data/inputs').glob('*.json'):
            if p.name in ['species_registry.json','research_matrix.json','public_sources.json','state_definition.json']:continue
            doc=json.loads(p.read_text())
            if pid=='paper_534ae3b6e2fb695f':
                if p.name=='monomers.json':
                    for x in doc['molecules']:
                        if x['id']=='TMC':x['role']='Mandatory first-acylation reactant for the upgraded matrix; not a ranked diamine.'
                    doc['boundary']='Molecular identities retained; new task.md defines the first-acylation reaction boundary.'
                else:doc['completion']='The expanded task requires actual TMC acylation paths, descriptors and distortion controls; see research_matrix.json.'
            if pid=='paper_6f9a36fff6964313':doc['identity_note']='Catalyst identities retained. The expanded complete object includes epoxide, KI, water and CO2; see species_registry.json and research_matrix.json. TFAP is context-only and not an additional required path.'
            if pid=='paper_d3b4575397179146':doc['scope']='Molecular identities retained; ground/excited/redox state and oxygen/substrate cycles required by task.md.'
            dump(p,doc)
        registry=build_species(pid,s,agent)
        if pid=='paper_60f4c45810428116':dump(agent/'data/inputs/kinetic_observations.json',json.loads((B/'kinetic_observations_transcription.json').read_text()))
        dump(agent/'data/inputs/research_matrix.json',{'paper_id':pid,'scientific_class':s['new_class'],'development_status':status,'definition':s['boundary'],'panels':{k:{'requirement':v['text'],'required_cells':v['schema'].get('required',[])} for k,v in s['panels'].items()},'optional_not_required':source_record['first_version_spec']['optional'],'input_blockers':s['blocked'] or [],'numeric_reference_status':'Not yet calibrated for expanded matrix; no new reference calculation performed.'})
        dump(agent/'data/inputs/public_sources.json',{'paper_id':pid,'source_locators':[{'document':Path(r['path']).name,'pdf_pages_1_based':r['pdf_pages_1_based'],'use':'Identity/experimental conditions only; do not retrieve target-paper answers.'} for r in sources],'new_control_origin':'Benchmark-authored definitions, explicitly distinguished from source results in task.md; registry graphs are not quantum-optimized reference endpoints.','limitations':s['notes']})
        intro='# Scientific objective\n\n'+s['title']+'. Establish the conclusion from the finite comparison matrix and auditable raw evidence.\n\n'
        if mode=='paper_reproduction':intro+='# Author-provided scientific guidance\n\n'+s['author']+'\n\n'
        public='# Public inputs and scientific boundaries\n\n'+s['boundary']+'\n\nUse `data/inputs/species_registry.json`, `research_matrix.json`, the retained molecular files and `public_sources.json`. Explicit registry definitions supersede old context-only scope notes. Author TS/terminal coordinates, raw reference outputs and historical PASS records are private. Do not read the target paper/SI, evaluator or historical verification archive as agent inputs. The supplied experimental observations are authorized interpretation constraints, never blind held-out predictions. General software documentation may be consulted.\n\n'
        if s['blocked']:public+='**Development input gate — blocked.** '+ ' '.join(s['blocked'])+' This package defines the completed development contract, but the scientific task must not be released as runnable until those items are supplied. A bounded failure can document the missing data; it cannot pass the intended expanded science.\n\n'
        required='# Required scientific validation/investigation\n\n'+'\n\n'.join(s['steps'])+'\n\nPreserve raw inputs, successful and failed searches, converged geometries, mode displacements, both path endpoints and analysis code. TS claims require one chemically relevant unstable mode and bidirectional connection or equally explicit mode-following/endpoint evidence; a scan maximum alone is not a TS. Genuine basin collapse or a resolved shallow pathway is allowed with complete observed profiles, mapping and limits. Missing core comparisons cannot be relabelled as uncertainty. Use one meaningful numerical, conformational or method sensitivity with actual changed calculations. Record real engine starts, allocated cores, summed job hours, core-hours and elapsed calendar hours separately.\n\nFirst-version exclusions: '+source_record['first_version_spec']['optional']+'\n\n'
        # All task prose is English, including optional boundaries originally supplied in Chinese.
        optional_english={
          'paper_3235db287859287e':'Full electrode processes, all substrates and the full reaction network are optional.',
          'paper_4e9774f4128551d3':'Full silylation/desilylation networks and every substrate are optional.',
          'paper_60f4c45810428116':'Full flow optimization and C-class pathway discovery are optional future work.',
          'paper_db6c4e0558113873':'The full photoredox/copper cycle and all substrates are optional.',
          'paper_e2d9397dff2a3f0f':'All three ligands and the full ammonia activation/PCET/N–N/NO network are optional.',
          'paper_fcc3c7f2c46a0fbe':'Exact IC50 prediction and biological oxidation networks are optional.',
          'paper_0e835b370ddd37b6':'Acetylene, ammonia-borane and full CO2 catalytic networks are optional.',
          'paper_9132719dbf91c978':'The full photocatalytic cycle and exact turnover frequencies are optional.',
          'paper_534ae3b6e2fb695f':'Polyamide fragment dynamics, interfacial diffusion and membrane MD are optional.',
          'paper_6f9a36fff6964313':'Epoxidation and the remainder of the catalytic cycle are optional.',
          'paper_c625cba3ce868eb1':'Enzyme QM/MM and the full biocatalytic environment are optional.',
          'paper_d3b4575397179146':'Full oxidation kinetics and all substrates are optional.',
          'paper_ef26687d63a37e29':'Long polymer chains, molecular-weight distributions and complete kinetic networks are optional.',
          'paper_0dc85595cab7bc0a':'SHARC/full photodynamics and exact photoproduct branching ratios are optional.',
          'paper_a3892396b1843698':'Large trajectory ensembles and every bridged derivative are optional.',
          'paper_8fefc96b015c4577':'The full radical network, every additive and exact product ratios are optional.'}
        required=required.replace(source_record['first_version_spec']['optional'],optional_english[pid])
        deliver='# Deliverables\n\nSubmit `report/results.json` conforming to `submission_schema.json` and a readable `report/report.md`. Required result panels:\n\n'+'\n'.join('- `'+k+'`: '+v['text'] for k,v in s['panels'].items())+'\n\nInclude methods, actual calculation records, at least two evidence-tested hypotheses, quantitative sensitivity, resource accounting and an evidence-bound conclusion. All cited files must exist below workspace `outputs/`, `data/` or `code/`. IDs and atom maps must resolve unambiguously. `complete` requires the whole core matrix, while `bounded_failure` preserves genuine attempted work, diagnostics and missing endpoints without inventing quantities. A documented input/capability failure before any engine or analysis job uses `failure_report.stage=pre_engine`, empty `calculation_records`, empty `methods`, zero scientific job counters and real preparation diagnostics; no fictional job log is required. Format acceptance is not scientific acceptance. Supported, refuted and evidence-complete indistinguishable conclusions are equally eligible; an author winner is not required.\n'
        (agent/'task.md').write_text(intro+public+required+deliver)
        schema=make_schema(pid,s);dump(agent/'submission_schema.json',schema)
        guide='# Submission guide\n\nThe schema is the exact field contract. A JSON-valid submission is not a scientific PASS.\n\n'
        guide+='Each `calculation_records` entry identifies a real input, raw log, method, object, charge/spin and job. A `minimum` or `transition_state` needs the corresponding geometry and state/curvature evidence. `constrained_diagnostic` is never a free minimum. Electronic energy is hartree; the thermal G correction includes ZPE, so G=E+thermal_G_correction without adding ZPE twice. For a composite method retain both constituent jobs and the exact assembly equation. Every record ID in a panel must resolve, and every cited evidence file must contain the claimed data.\n\n'
        guide+='For every path, report local and common separated-reactant/reservoir reference, all spectators, temperature and standard state. `gibbs_barrier_kcal_mol` uses the common reference; `preorganization_G_kcal_mol` is immediate-precursor minus that reference. Recover the local barrier by subtraction. Electrode/proton terms are needed only when stoichiometry changes. Do not compare raw total energies between different formulas or electronic states. A validated saddle requires its negative frequency, actual displacement and both endpoint artifacts. `evidenced_collapse`/`evidenced_no_distinct_saddle` requires a sampled profile and explicit exclusions; no fictitious zero barrier is required.\n\n'
        guide+='`PAIR`-style comparisons use right-minus-left and require numeric operands, source IDs and the common definition. For strain/interaction panels, strain = (E_A_frozen−E_A_relaxed)+(E_B_frozen−E_B_relaxed); interaction=E_AB−E_A_frozen−E_B_frozen; total=E_AB−E_A_relaxed−E_B_relaxed. Convert hartree consistently, state counterpoise and fragment charge/spin, and report the closure residual. Compare identical reaction progress.\n\n'
        guide+='Sensitivity difference = alternative−baseline from genuinely different settings. Hypotheses must cite discriminatory evidence, not merely restate the prompt. A failed launched calculation may omit uncomputed result panels but requires `failure_report`, its actual raw attempt logs and `conclusion.assessment=incomplete`. A pre-engine input or capability gate instead uses `failure_report.stage=pre_engine`, `calculation_records=[]`, `methods={}`, actual diagnostic files, the missing endpoints and a specific cause. All scientific job counters, core allocations and job/core hours must be zero; elapsed preparation time may be nonzero. Do not submit uncomputed result panels, hypotheses or sensitivity, and do not fabricate a calculation input or log. Both failure forms are admissible diagnostics and cannot earn scientific completion. Do not fill missing values with guessed numbers. Evidence paths may begin with `./` or contain harmless `./` segments; absolute paths and any `..` segment are forbidden.\n\n'
        guide+='For `comparison_outcome=numeric_difference`, all numeric operands are required. `same_basin_after_evidenced_collapse` permits omission of nonexistent separate energies only with independent search records, mapped retained-basin evidence and complete profiles. It is not available merely because a solver failed. In a multistep path, `sequence_segments` must cover all chemically necessary transformations and the effective-maximum ledger must place every segment on one starting inventory; the outer path identifies the controlling segment, without summing activation barriers. For candidate exclusions/collapse, supply the mapped exclusion trace instead of an invented relative G.\n\n'
        guide+='\n\n'.join('## `'+k+'`\n\n'+v['text'] for k,v in s['panels'].items())+'\n'
        (agent/'submission_guide.md').write_text(guide)
        for name,value in evaluator(pid,s,sources).items():dump(target/'evaluation'/name,value)
        validation='# Expanded-reference validation plan\n\nStatus: '+status+'. No new scientific calculations have been performed. No upgraded scientific PASS is claimed.\n\n'
        validation+='## Source actually inspected\n\n'+'\n'.join('- `'+r['path']+'`, PDF pages '+', '.join(map(str,r['pdf_pages_1_based']))+'; SHA256 '+r['sha256'] for r in sources)+'\n\n'+s['author']+'\n\n'
        validation+='## Reusable old evidence and new gaps\n\nThe entire old final payload is preserved byte-for-byte in `legacy_final_snapshot/`. The former scalar/descriptor/local-path calculation is reusable only for the same object, state, method and observable. It does not validate the expanded matrix. Inspect the old raw evidence pointers in the archived source evaluator and audit; never reuse its old PASS as a completion result.\n\nNew required reference gaps:\n\n'+'\n'.join('- '+k+': '+v['text'] for k,v in s['panels'].items())+'\n\n'
        validation+=NOTES[pid]['reuse']+'\n\nHistorical structured reports directly inspected in this development pass:\n\n'+'\n'.join('- `'+r['path']+'`; SHA256 '+r['sha256'] for r in HISTORY[pid])+'\n\n'
        if s['blocked']:validation+='## Blocking inputs and release conditions\n\n'+'\n'.join('- '+x for x in s['blocked'])+'\n\n'
        validation+='## Minimum pilot and full validation\n\n1. Verify all graphs, hydrogens, maps, formal charge/spin and reaction ledgers; rebuild only independent reactant/candidate starters. Check the exact source excerpts and noted conflicts.\n2. Reproduce one relevant old baseline and the most decisive new competing control. Check saddle mode and bidirectional endpoints, or state/parameter identity for non-path analyses. Preserve failed/restarted jobs.\n3. Complete every named panel and compare at common zeros. Run one decisive model/conformer/method perturbation. Establish experimental extraction error, numerical convergence and method spread before setting any numerical tolerance.\n4. Calibrate real complete/supporting, complete/refuting-or-indistinguishable, old-only and wrong-state/reference submissions. Run AR independently without author answers; do not fabricate an autonomous search history from PR evidence.\n5. Measure actual engine starts, allocations and scientific job time before setting a budget; matrix cell counts are not engine calls.\n\n'
        validation+='### Paper-specific pilot order\n\n'+NOTES[pid]['pilot']+'\n\n### Scientific adversarial calibration (not executed here)\n\n'+NOTES[pid]['adversarial']+'\n\n'+NOTES[pid]['fair_alternative']+'\n\n'
        validation+='## Callable software and limits\n\nUse current chemistry_toolbox/README.md, config/mcp_profiles.yaml and config/native_software_guides.yaml: Gaussian/ORCA for molecular optimization, frequencies, TD/redox; pysisyphus/IRC or explicit mode following for paths; CREST/xTB only for preparation, not substitute final DFT barriers; Multiwfn for exported wavefunction analyses and Python/SciPy for audited arithmetic/ODEs. A specific method is not validated merely because its program is installed. NBO/PyFrag are optional if available. No new paid service, HPC job or long computation was launched here.\n\n## Scope-specific failure checks\n\n'+s['errors']+'\n'
        (target/'evaluation/reference_validation_plan.md').write_text(validation)
        if (target/'paper_route.md').exists():(target/'paper_route.md').write_text('# Upgraded author-route and scope record\n\n'+s['author']+'\n\n'+s['boundary']+'\n\nThe AR public prompt excludes this route. AR and PR share objects, schema, scientific rubric and completion requirements. Development status: '+status+'. Old route and old PASS are historical only in the snapshot.\n')
        info=json.loads((src/'task_info.json').read_text());info['title']=s['title'];info['category']='bounded scientific hypothesis testing' if s['new_class']=='B' else 'bounded pathway and candidate discovery';info['difficulty']='hard';info['difficulty_reasons']=['Connected chemical alternatives, controlled comparisons and common-reference observables are required.','Identity/state and raw-evidence validation, sensitivity and bounded conclusions replace the former narrow endpoint.'];info['data']=[{'path':'data/inputs','description':'Complete retained identities, new atom-mapped species and explicit finite comparison matrix.'}];info['required_deliverables']=[{'path':'report/results.json','description':'Expanded structured scientific matrix and audit records.'},{'path':'report/report.md','description':'Readable evidence-bound investigation with raw artifact links.'}];dump(target/'task_info.json',info)
        source_docs=[{'path':'docs/evalution/update/'+pid+'.md','sha256':sha(ROOT/'docs/evalution/update'/f'{pid}.md')},{'path':'docs/evalution/update/upgrade_implementation_guide_20260927.md','sha256':sha(ROOT/'docs/evalution/update/upgrade_implementation_guide_20260927.md')},{'path':'docs/evalution/update/upgrade_guidance_review_20260927.md','sha256':sha(ROOT/'docs/evalution/update/upgrade_guidance_review_20260927.md')},{'path':'docs/evalution/update/upgrade_guidance_review_manifest_20260927.json','sha256':sha(ROOT/'docs/evalution/update/upgrade_guidance_review_manifest_20260927.json')}]
        dump(auditpath,{'paper_id':pid,'task_type':mode,'date':'2026-09-27','implementation_owner':'batch4.build_batch','source':str(src.relative_to(ROOT)),'source_package_manifest_sha256':sha(src/'package_manifest.json'),'source_package_content_sha256':json.loads((src/'package_manifest.json').read_text()).get('package_content_sha256'),'source_payload_snapshots':snapshot_records,'source_docs':source_docs,'source_pdf_review':sources,'old_class':source_record['current_class'],'new_class':s['new_class'],'status':status,'new_scientific_calculations_performed':False,'scientific_engine_starts':0,'new_reference_gaps':list(s['panels']),'input_blockers':s['blocked'] or [],'short_checks_performed':['RDKit graph/formula/charge inspection','Source-page extraction and selected figure inspection','Package/contract checks recorded in batch validation_report.json'],'historical_evidence_policy':'Old reference data/PASS remain private snapshots, never certification of this expanded version.'})
        refresh(target,pid,mode);packages.append(str(target.relative_to(ROOT)))
    return {'paper_id':pid,'packages':packages,'old_class':source_record['current_class'],'new_class':s['new_class'],'status':status,'new_reference_gaps':[v['text'] for v in s['panels'].values()],'blockers':s['blocked'] or [],'source_pages_reviewed':sources,'new_scientific_calculations_performed':False,'checks':'pending batch contract/runtime/export regression'}

def main():
    done={}
    manifest=B/'manifest.json'
    if manifest.exists():done={x['paper_id']:x for x in json.loads(manifest.read_text()).get('papers',[])}
    selected=sys.argv[1:] or IDS
    for pid in selected:
        if pid not in IDS:raise ValueError(pid)
        rec=build_one(pid);done[pid]=rec
        dump(manifest,{'batch':4,'date':'2026-09-27','scope':IDS,'scientific_engine_starts':0,'papers':[done[x] for x in IDS if x in done]})
        status_write(done)
        print(pid,rec['status'],flush=True)
    dump(B/'implemented_specifications.json',{k:{a:v for a,v in s.items() if a!='panels'}|{'panels':{a:b['text'] for a,b in s['panels'].items()}} for k,s in SPECS.items()})
if __name__=='__main__':main()
